export function drawPrinterOverlay(c,g,w,h){if(!g.rooms)return;const alpha=roomFade(g);if(alpha>0){c.fillStyle=`rgba(7,17,29,${Math.min(1,alpha)})`;c.fillRect(0,0,w,h);}drawDawn(c,g,w,h);}
